/**
 * HTML as CKEditor 4 wrote it, from what Tiptap writes: the rich text blocks keep the markup the
 * frontend templates and stylesheets were written for.
 *
 *  - attributes CKEditor wrote are kept through the schema (preserveAttributes(): class and style on
 *    blocks, list items and table parts, style limited to safeStyle(); border, cellpadding,
 *    cellspacing on tables)
 *  - a list item or table cell whose content is one plain paragraph (and, in a list item, nested
 *    lists) is written without the <p>, as CKEditor did: <li>a</li>, <td>x</td>
 *  - <pre><code>…</code></pre> without a language becomes <pre>…</pre>
 *  - links carry href first, as CKEditor wrote them
 *  - styles are written as CKEditor wrote them: "text-align:center", declarations joined by "; "
 *    (alignment with the justify plugin's default, a style, not a class: the bundle set no
 *    justifyClasses, vendor/ckeditor/config.js neither)
 *
 * The table itself is written without Tiptap's <colgroup> and min-width (tableWithoutColgroup()).
 *
 * @license GPL-2.0-or-later
 */
/**
 * Small helpers shared by the two editors: the interface texts and the event lists.
 *
 * @license GPL-2.0-or-later
 */
/**
 * The rich text editor of the layout editor: Tiptap on the block's .rich-text-editor element, with
 * the toolbar CKEditor 4 had there (the bundle's configuration, javascript/netgen-layouts.js,
 * module rich_text): undo/redo, paragraph format (paragraph, heading 1-3, preformatted), bold,
 * italic, underline, strikethrough, link (target only "new window" or none), bulleted and numbered
 * list with indent, block quote, alignment, horizontal line, table, remove formatting.
 *
 * Reads and writes HTML. What CKEditor stored loads as before: <p>, <h1>-<h6>, <pre>, <strong>/<b>,
 * <em>/<i>, <u>, <s>/<del>/<strike>, <a href target>, <ul>/<ol>/<li>, <blockquote>, <hr>, <br>,
 * <table> and style="text-align: ..." on paragraphs and headings.
 *
 * @license GPL-2.0-or-later
 */
/**
 * window.CKEDITOR for the layout editor's bundle (javascript/netgen-layouts.js), backed by Tiptap.
 * CKEditor 4 is no longer loaded; this covers exactly what the bundle calls (module rich_text):
 *
 *   CKEDITOR.on( 'instanceCreated', fn )     fn( evt ), evt.editor; the editor then fires 'configLoaded'
 *   CKEDITOR.on( 'dialogDefinition', fn )    kept, never fired: the link form offers only the targets
 *                                            the bundle allowed there ("new window" or none)
 *   CKEDITOR.inline( element )               → editor
 *   CKEDITOR.instances                       name → editor
 *   editor.config.readOnly = true            editor.config is the bundle's to write; readOnly is applied
 *   editor.on( 'change', fn )                fn called with the editor as this
 *   editor.getData() / setData( html )
 *   editor.setReadOnly( [bool] )             no argument: read-only, as in CKEditor
 *   editor.focus() / editor.destroy( [noUpdate] )
 *
 * @license GPL-2.0-or-later
 */
/**
 * The code editor of the layout editor (HTML snippet and Markdown blocks): a Tiptap document of
 * exactly one code block, highlighted with lowlight. Plain text in, the same plain text out: the
 * value is the text of the code block, byte for byte, line breaks and a trailing newline included.
 *
 * Tab inserts spaces up to the next tab stop (Shift+Tab takes them away again, on every selected
 * line), Enter keeps the indentation of the line; Escape leaves the editor so the keyboard can move on.
 *
 * @license GPL-2.0-or-later
 */
/**
 * window.ace for the layout editor's bundle (javascript/netgen-layouts.js), backed by Tiptap.
 * The Ace editor is no longer loaded; this covers exactly what the bundle calls (module ace_editor,
 * used by the HTML snippet and Markdown blocks):
 *
 *   ace.edit( element )                         → editor, the element's text is the value
 *   editor.getSession()                         → session: setMode( 'ace/mode/…' ), setTabSize( n ),
 *                                                 setUseSoftTabs( bool ), on( 'changeAnnotation', fn ),
 *                                                 getAnnotations() / setAnnotations( list )
 *   editor.setTheme() / setHighlightActiveLine() accepted, the look comes from the stylesheet
 *   editor.commands.addCommand( { name, bindKey: { win, mac }, exec } )
 *   editor.on( 'change', fn )                   fn( delta, editor )
 *   editor.getValue() / setValue( text )
 *   editor.container                            the element (the bundle sets style.pointerEvents)
 *   editor.renderer.setStyle( 'disabled', on )  also makes the text read-only while disabled
 *   editor.focus() / blur() / resize() / destroy()
 *
 * @license GPL-2.0-or-later
 */
/**
 * The editors of the layout editor, built on Tiptap: window.CKEDITOR (rich text) and window.ace
 * (HTML snippet, Markdown) with exactly the calls javascript/netgen-layouts.js makes of them.
 * Loaded before that bundle (app.tpl): its rich text module registers CKEDITOR listeners as soon
 * as it is evaluated.
 *
 * @license GPL-2.0-or-later
 */
